// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for site rules wired into the ladder, judge, walk and records
// Flo: mock site on 127.0.0.1 with one site rule > fetch or walk > assert the rule changed behavior
// I/O: mock server + mock vendor > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const cfgz = @import("cf-conf-load.zig"); const walk = @import("ru-page-walk.zig"); const inde = @import("st-page-inde.zig"); const mock = @import("te-mock-serv.zig");
const allo = std.testing.allocator;
fn ruleConf(aren: std.mem.Allocator, extr: []const u8) !cfgz.Conf { const text = try std.fmt.allocPrint(aren, "{{\"site_rule_list\":[{{\"name\":\"tst\",\"host\":[\"127.0.0.1\"],{s}}}]}}", .{extr}); return cfgz.confPars(aren, text); }
fn bare(rigg: *rigz.Rigg) void { rigg.ladz.sess = null; }
test "tier_maxz 1 forbids every vendor for the site" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"tier_maxz\":1")); defer rigg.down(); bare(&rigg); try std.testing.expectError(error.OverCap, rigg.gozz("/e403")); try std.testing.expectEqual(@as(usize, 0), rigg.vmkz.cal3.items.len); }
test "vend_bann_list skips a vendor for this site" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"vend_bann_list\":[\"deco\"]")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/e403"); try std.testing.expectEqualStrings("zenr", outc.vend); }
test "tier_star rend skips the bare vendor tier; capz_cred_pagz picks the vendor under the cap" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"tier_star\":\"rend\",\"capz_cred_pagz\":1")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/e403"); try std.testing.expectEqualStrings("brig", outc.vend); try std.testing.expect(rigg.vmkz.cal3.items[0].mode == .rend); }
test "tier_skip_list own: the own GET never happens" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"tier_skip_list\":[\"own\"]")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/p1"); try std.testing.expect(outc.tier >= 2); try std.testing.expectEqual(@as(u32, 0), rigg.srv2.hits.load(.monotonic)); }
test "judg_must_list: a page without the phrase is treated as bad, with it the free tier wins" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"judg_must_list\":[\"NOT-ON-THE-PAGE\"]")); defer rigg.down(); bare(&rigg); try std.testing.expectError(error.Blocked, rigg.gozz("/p1")); try std.testing.expect(rigg.vmkz.cal3.items.len >= 1); var rig2: rigz.Rigg = undefined; try rig2.upzz(try ruleConf(carn.allocator(), "\"judg_must_list\":[\"Item 1\"]")); defer rig2.down(); bare(&rig2); const outc = try rig2.gozz("/p1"); try std.testing.expectEqual(@as(i64, 1), outc.tier); }
test "judg_bloc_list and judg_text_minz reject otherwise fine pages" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"judg_bloc_list\":[\"real\"]")); defer rigg.down(); bare(&rigg); try std.testing.expectError(error.Blocked, rigg.gozz("/p1")); var rig2: rigz.Rigg = undefined; try rig2.upzz(try ruleConf(carn.allocator(), "\"judg_text_minz\":5000")); defer rig2.down(); bare(&rig2); try std.testing.expectError(error.Blocked, rig2.gozz("/p1")); }
test "judg_fiel_requ: a JSON reply with an empty required field is rejected" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"judg_fiel_requ\":[\"missing_field\"],\"apiz_prob_enab\":true")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/spa"); try std.testing.expect(outc.tier >= 2 or !std.mem.eql(u8, outc.kind, "json")); }
test "shel_mark_list: a site marker makes a small page a shell, vendor render follows" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"shel_mark_list\":[\"Item 1\"],\"apiz_prob_enab\":false")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/p1"); try std.testing.expect(outc.tier >= 3); }
test "apiz_path_list: an extra candidate path is probed and wins" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"apiz_path_list\":[\"/api/items\"]")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/spacust"); try std.testing.expectEqualStrings("json", outc.kind); try std.testing.expectEqual(@as(usize, 0), rigg.vmkz.cal3.items.len); }
test "brow_wait_msec as a site default forces a render and reaches the vendor" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"brow_wait_msec\":1500")); defer rigg.down(); bare(&rigg); _ = try rigg.gozz("/e403"); try std.testing.expect(rigg.vmkz.cal3.items[0].mode == .rend); try std.testing.expectEqual(@as(u32, 1500), rigg.vmkz.cal3.items[0].wait); }
test "a missing steps file is a config error, not a silent skip" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"brow_step_file\":\"no-such-steps.json\"")); defer rigg.down(); bare(&rigg); try std.testing.expectError(error.BadConfig, rigg.gozz("/p1")); }
test "extr_pref_list text: JSON-LD is ignored for this site" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"extr_pref_list\":[\"text\"]")); defer rigg.down(); bare(&rigg); const outc = try rigg.gozz("/p2"); try std.testing.expectEqualStrings("text", outc.kind); var rig2: rigz.Rigg = undefined; try rig2.upzz(.{}); defer rig2.down(); bare(&rig2); const base = try rig2.gozz("/p2"); try std.testing.expectEqualStrings("ldjs", base.kind); }
fn walkRigg(carn: std.mem.Allocator, extr: []const u8, foll: u32, seed: []const u8, outz: *walk.Summ) !void { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srvz: mock.Mock = undefined; try srvz.sta2(std.testing.io); defer srvz.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wlkz = walk.Walk.init(allo, std.testing.io, try ruleConf(carn, extr), &dbzz, dirz, true); defer wlkz.deinit(); wlkz.gapz = 0; wlkz.base = 0; wlkz.foll = foll; var buff: [64]u8 = undefined; const urlz = try carn.dupe(u8, srvz.urlzOfzz(&buff, seed)); _ = try wlkz.walkSeed(&.{urlz}); outz.* = try wlkz.walkRunz(null); }
test "walk: retr_code_list sends a non-listed status straight to the dead list" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var sumz: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"retr_code_list\":[429]", 0, "/e403", &sumz); try std.testing.expectEqual(@as(u32, 1), sumz.fail); var sum2: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"rate_host_seco\":0", 0, "/e403", &sum2); try std.testing.expectEqual(@as(u32, 3), sum2.fail); }
test "walk: foll_excl_list, foll_incl_list and foll_maxz shape which links are queued" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var sumz: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"foll_excl_list\":[\"/p2\",\"/p3\"]", 10, "/hub2", &sumz); try std.testing.expectEqual(@as(u32, 2), sumz.done); var sum2: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"foll_incl_list\":[\"/p3\"]", 10, "/hub2", &sum2); try std.testing.expectEqual(@as(u32, 2), sum2.done); var sum3: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"foll_maxz\":2", 10, "/hub2", &sum3); try std.testing.expectEqual(@as(u32, 3), sum3.done); var sum4: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"rate_host_seco\":0", 10, "/hub2", &sum4); try std.testing.expectEqual(@as(u32, 4), sum4.done); }
test "walk: rate jitter and a per-site pace still finish the run" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var sumz: walk.Summ = .{}; try walkRigg(carn.allocator(), "\"rate_host_seco\":0,\"rate_jitt_pctz\":50", 10, "/hub2", &sumz); try std.testing.expectEqual(@as(u32, 4), sumz.done); }
test "brow_blok_resz: images are not loaded for this site, other sites still get them" { var carn = std.heap.ArenaAllocator.init(allo); defer carn.deinit(); var rigg: rigz.Rigg = undefined; try rigg.upzz(try ruleConf(carn.allocator(), "\"brow_blok_resz\":true")); defer rigg.down(); try rigg.skipNozz(); _ = try rigg.gozz("/imgs"); const reck = (try rigg.reco("/imgs")).?; try std.testing.expect(std.mem.indexOf(u8, reck.body, "Image status: blocked") != null); var rig2: rigz.Rigg = undefined; try rig2.upzz(.{}); defer rig2.down(); try rig2.skipNozz(); _ = try rig2.gozz("/imgs"); const rec2 = (try rig2.reco("/imgs")).?; try std.testing.expect(std.mem.indexOf(u8, rec2.body, "Image status: loaded") != null); }
